import csv, json, sys, os
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal, ROUND_HALF_UP
from zoneinfo import ZoneInfo

UTC = timezone.utc


def rows_csv(path, delim=','):
    with open(path, encoding='utf-8-sig', newline='') as f:
        txt = f.read()
    lines = [l for l in txt.splitlines() if l.strip()]
    rdr = csv.reader(lines, delimiter=delim)
    hdr = [h.strip() for h in next(rdr, [])]
    for r in rdr:
        if not r:
            continue
        yield {h: (r[i] if i < len(r) else '') for i, h in enumerate(hdr)}


def local_to_utc(naive, zone, abbr_dst=None):
    """naive local datetime -> aware UTC datetime. abbr_dst: True/False/None picks repeated time;
    None means first occurrence."""
    a = naive.replace(tzinfo=zone, fold=0)
    b = naive.replace(tzinfo=zone, fold=1)
    if a.utcoffset() == b.utcoffset():
        return a.astimezone(UTC)
    if abbr_dst is None:
        return a.astimezone(UTC)
    for c in (a, b):
        if bool(c.dst()) == abbr_dst:
            return c.astimezone(UTC)
    return a.astimezone(UTC)


def norm_dir(s):
    s = s.strip().upper()
    return 'IN' if s in ('IN', 'I', 'CLOCK_IN', 'K') else 'OUT'


def read_site(site, zone, fmt, d):
    """yield (punch_id, emp, dir, instant)"""
    files = []
    for root, _, fs in os.walk(d):
        for fn in fs:
            files.append(os.path.join(root, fn))
    files.sort()
    for p in files:
        if fmt == 'abbr-csv':
            for r in rows_csv(p):
                t = datetime.strptime(r['Date'].strip() + ' ' + r['Time'].strip().upper(), '%m/%d/%Y %I:%M:%S %p')
                ab = r.get('Zone', '').strip().upper()
                dst = True if ab.endswith('DT') else (False if ab.endswith('ST') else None)
                yield r['Record'].strip(), r['Badge'].strip(), norm_dir(r['Punch']), local_to_utc(t, zone, dst)
        elif fmt == 'epoch-jsonl':
            with open(p, encoding='utf-8-sig') as f:
                for line in f:
                    if not line.strip():
                        continue
                    o = json.loads(line)
                    if o.get('heartbeat'):
                        continue
                    if 'ts_ms' in o:
                        s = int(o['ts_ms']) // 1000
                    else:
                        s = int(o['ts'])
                    yield str(o['id']), str(o['emp']).strip(), norm_dir(o['dir']), datetime.fromtimestamp(s, UTC)
        elif fmt == 'offset-csv':
            for r in rows_csv(p, ';'):
                ts = r['timestamp'].strip()
                if ts.endswith('Z'):
                    ts = ts[:-1] + '+00:00'
                yield r['punch_id'].strip(), r['employee'].strip(), norm_dir(r['event']), datetime.fromisoformat(ts).astimezone(UTC)
        elif fmt == 'legacy-fixed':
            std = None
            with open(p, encoding='utf-8-sig', newline='') as f:
                for line in f.read().splitlines():
                    if not line.strip() or line[0] != 'D':
                        continue
                    pid = line[1:9]
                    badge = line[9:15].strip()
                    dr = line[15]
                    t = datetime.strptime(line[16:30], '%Y%m%d%H%M%S')
                    probe = t.replace(tzinfo=zone)
                    off = probe.utcoffset() - (probe.dst() or timedelta(0))
                    inst = (t - off).replace(tzinfo=UTC)
                    yield pid, 'E' + badge, norm_dir(dr), inst
        elif fmt == 'de-tsv':
            for r in rows_csv(p, '\t'):
                t = datetime.strptime(r['Datum'].strip() + ' ' + r['Uhrzeit'].strip(), '%d.%m.%Y %H:%M')
                z = r.get('Zeitzone', '').strip().upper()
                dst = True if z == 'MESZ' else (False if z == 'MEZ' else None)
                yield r['Nr'].strip(), r['Ausweis'].strip(), norm_dir(r['Buchung']), local_to_utc(t, zone, dst)
        elif fmt == 'local-csv':
            for r in rows_csv(p):
                t = datetime.strptime(r['local_time'].strip(), '%Y-%m-%d %H:%M:%S')
                yield r['punch_ref'].strip(), r['employee_id'].strip(), norm_dir(r['direction']), local_to_utc(t, zone)
        elif fmt == 'local-jsonl':
            with open(p, encoding='utf-8-sig') as f:
                for line in f:
                    if not line.strip():
                        continue
                    o = json.loads(line).get('punch')
                    if not o:
                        continue
                    i = o['id']
                    i = str(int(i)) if isinstance(i, (int, float)) or str(i).isdigit() else str(i)
                    t = datetime.strptime(o['at'].strip(), '%Y-%m-%d %H:%M:%S')
                    yield i, str(o['badge']).strip(), norm_dir(o['type']), local_to_utc(t, zone)
        else:
            raise SystemExit('unknown format ' + fmt)


