    cutoff = datetime.fromisoformat(period['corrections_cutoff'].replace('Z', '+00:00'))
    sites = {r['site'].strip(): (ZoneInfo(r['timezone'].strip()), r['format'].strip())
             for r in rows_csv(os.path.join(inp, 'sites.csv'))}
    emps = {}
    for r in rows_csv(os.path.join(inp, 'employees.csv')):
        emps[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    for r in rows_csv(os.path.join(inp, 'rates.csv')):
