                punches[k] = [r['employee'].strip(), norm_dir(r['type']),
                              datetime.fromisoformat(r['time'].strip().replace('Z', '+00:00')).astimezone(UTC)]
                applied += 1

    # group by employee, discard unknown
    by_emp = {}
    for (site, pid), (emp, dr, inst) in punches.items():
        if emp in emps:
            by_emp.setdefault(emp, []).append((inst, 0 if dr == 'OUT' else 1, site, pid, dr))

    def rnd(inst, zone):
        off = inst.astimezone(zone).utcoffset()
        loc = inst + off
        s = (loc.minute * 60 + loc.second) % 360
        delta = -s if s < 180 else 360 - s
        return inst.replace(microsecond=0) + timedelta(seconds=delta)

    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)
    res = {}
    for e, home in emps.items():
        res[e] = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Decimal(0))
    hz = {e: sites[h][0] for e, h in emps.items()}

    def inperiod(rinst, e):
        wd = rinst.astimezone(hz[e]).date()
        return wd, pstart <= wd <= pend

    for e, lst in by_emp.items():
        lst.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        kept = []
        for inst, _, site, pid, dr in lst:
            r = rnd(inst, sites[site][0])
            if kept and kept[-1][4] == dr and (inst - kept[-1][0]).total_seconds() <= 300:
                if inperiod(r, e)[1]:
                    exc['duplicates_dropped'] += 1
                continue
            kept.append((inst, 0, site, pid, dr, r))
        shifts = []
        pend_in = None
        def open_(p):
            if inperiod(p[5], e)[1]:
                exc['open_shifts'] += 1
        for p in kept:
            if p[4] == 'IN':
                if pend_in:
                    open_(pend_in)
                pend_in = p
            else:
                if pend_in and (p[5] - pend_in[5]) <= timedelta(hours=16):
                    shifts.append((pend_in, p))
                    pend_in = None
                else:
                    if pend_in:
                        open_(pend_in)
                        pend_in = None
                    if inperiod(p[5], e)[1]:
                        exc['orphan_outs'] += 1
        if pend_in:
            open_(pend_in)
