                h = t.astimezone(zone).hour
                if h >= 22 or h < 6:
                    night += 1
                t += timedelta(minutes=1)
            night = min(night, paid)
            sl.append([i[5], wd, paid, night, 0])
        sl.sort(key=lambda x: x[0])
        daily = {}
        for s in sl:
            used = daily.get(s[1], 0)
            reg = max(0, min(s[2], 480 - used))
            s.append(s[2] - reg)  # daily ot -> index 5
            daily[s[1]] = used + s[2]
        weekly = {}
        for s in sl:
            wk = s[1] - timedelta(days=s[1].weekday())
            used = weekly.get(wk, 0)
            nd = s[2] - s[5]
            wot = max(0, used + nd - 2400) - max(0, used - 2400)
            weekly[wk] = used + nd
            s[4] = s[5] + wot
        r = res[e]
        rl = rates.get(e, [])
        for s in sl:
            rate = None
            for ef, v in rl:
                if ef <= s[1]:
                    rate = v
            if rate is None and rl:
                rate = rl[0][1]
            rate = rate or Decimal(0)
            reg = s[2] - s[4]
            r['shifts'] += 1
            r['paid_minutes'] += s[2]
            r['overtime_minutes'] += s[4]
            r['night_minutes'] += s[3]
            r['gross'] += rate * (Decimal(reg) + Decimal('1.5') * s[4]) / 60 + rate * Decimal('0.15') * s[3] / 60

    out_emps = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tg = Decimal(0)
    for e in sorted(res):
        r = res[e]
        g = r['gross'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        out_emps[e] = dict(shifts=r['shifts'], paid_minutes=r['paid_minutes'],
                           overtime_minutes=r['overtime_minutes'], night_minutes=r['night_minutes'],
                           gross='%.2f' % g)
        for k in tot:
            tot[k] += r[k]
        tg += g
    tot['gross'] = '%.2f' % tg
    with open(outp, 'w') as f:
        json.dump(dict(period=dict(start=period['start'], end=period['end']), employees=out_emps,
                       exceptions=exc, totals=tot), f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
